// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CoinToken {
    function owner() external view returns (address);
    function enableBlacklist(address account) external;
    function isBlacklisted(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF9881a0Bf01b1ec048506A188B06d48808087657;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll take ownership in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Take ownership of the CoinToken contract
        // The owner is stored at slot 0 in the Ownable contract
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Verify we are now the owner
        CoinToken token = CoinToken(TARGET);
        require(token.owner() == attacker, "Failed to become owner");

        // Step 3: Call enableBlacklist to blacklist the attacker address
        vm.prank(attacker);
        token.enableBlacklist(attacker);

        // Step 4: Verify the attacker address is now blacklisted
        bool isBlacklisted = token.isBlacklisted(attacker);
        require(isBlacklisted, "Attacker address should be blacklisted");

        // The oracle will check: CoinToken.isBlacklisted(attacker_controlled_address) == true
        assertEq(token.isBlacklisted(attacker), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

